sql_query:
SELECT "Secondary endpoint"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Secondary endpoint", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Name of ICI", '')) = 'Ipilimumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 2';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Secondary endpoint" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Secondary endpoint", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Name of ICI", '')) = 'Ipilimumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 2'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_irae_assessed(source_value) AS "irAE_assessed"
FROM base;
